const data = new Date(2025, 4, 1);
console.log(data.getFullYear(), data.getMonth(), data.getDate());
// 2025 4 1

const wigilia = new Date("2025-12-24T18:00:00");
console.log(wigilia.getFullYear()); // 2025
console.log(wigilia.getDate());     // 24

const start = new Date(2025, 0, 1);
const koniec = new Date(2025, 0, 20);

const roznicaMs = koniec.getTime() - start.getTime();
const dni = roznicaMs / (1000 * 60 * 60 * 24);
console.log(dni); // 19
